CREATE PROCEDURE "informix".sp_notif_cambios_portacec()
REFERENCING OLD AS pre NEW AS pos FOR sc_portacec_solicitud;

    DEFINE vCodigoRetorno CHAR(10);
    LET vCodigoRetorno = ''; 

    IF (pos.cta_ordenante != pre.cta_ordenante) THEN
        EXECUTE PROCEDURE bdimnsj:"informix".sp_registra_evento('1','MON_SMS','ALERT_SM','000000000','','','1','','','','','BD: WARNING! Cambio en cuenta portabilidad nomina','','','','','','','5539775952',1,0,0,0,0,current,'')
            INTO vCodigoRetorno;
        EXECUTE PROCEDURE bdimnsj:"informix".sp_registra_evento('1','MON_SMS','ALERT_SM','000000000','','','1','','','','','BD: WARNING! Cambio en cuenta portabilidad nomina','','','','','','','5523008024',1,0,0,0,0,current,'')
            INTO vCodigoRetorno;
        EXECUTE PROCEDURE bdimnsj:"informix".sp_registra_evento('1','MON_SMS','ALERT_SM','000000000','','','1','','','','','BD: WARNING! Cambio en cuenta portabilidad nomina','','','','','','','5543885549',1,0,0,0,0,current,'')
            INTO vCodigoRetorno;			
    END IF
    
    IF (pos.cta_receptora != pre.cta_receptora) THEN
        EXECUTE PROCEDURE bdimnsj:"informix".sp_registra_evento('1','MON_SMS','ALERT_SM','000000000','','','1','','','','','BD: WARNING! Cambio en cuenta portabilidad nomina','','','','','','','5539775952',1,0,0,0,0,current,'')
            INTO vCodigoRetorno;
        EXECUTE PROCEDURE bdimnsj:"informix".sp_registra_evento('1','MON_SMS','ALERT_SM','000000000','','','1','','','','','BD: WARNING! Cambio en cuenta portabilidad nomina','','','','','','','5523008024',1,0,0,0,0,current,'')
            INTO vCodigoRetorno;
        EXECUTE PROCEDURE bdimnsj:"informix".sp_registra_evento('1','MON_SMS','ALERT_SM','000000000','','','1','','','','','BD: WARNING! Cambio en cuenta portabilidad nomina','','','','','','','5543885549',1,0,0,0,0,current,'')
            INTO vCodigoRetorno;			
    END IF    
    
END PROCEDURE
DOCUMENT 
'Base de datos: bdicheq',
'Fecha: 11.JUNIO.2021',
'Envio de notificacion ante una actualizacion de los campos: ordenante o receptora'
