create view "informix".si_sucursales (empresa,sucursal,nombre,plaza) as 
  select x0.empresa ,x0.sucursal ,x0.nombre ,x0.plaza from bdinteg:
    "informix".si_sucursales x0 ;                             
                                                             
        
create view "informix".si_plazas (empresa,plaza,nombre,regional) as 
  select x0.empresa ,x0.plaza ,x0.nombre ,x0.regional from bdinteg:
    "informix".si_plazas x0 ;                                 
                                                             
            
create view "informix".si_regional (empresa,regional,nombre) as 
  select x0.empresa ,x0.regional ,x0.nombre from bdinteg:"informix"
    .si_regional x0 ;                                        
                                                             
                 
create view "informix".si_divisas (empresa,divisa,descripcion) as 
  select x0.empresa ,x0.divisa ,x0.descripcion from bdinteg:"informix"
    .si_divisas x0 ;                                         
                                                             
            
create view "informix".si_empresas (empresa,razon_social) as 
  select x0.empresa ,x0.razon_social from bdinteg:"informix".si_empresas 
    x0 ;                                                     
                                                             
              
create view "informix".si_ejecut (empresa,ejecutivo,nombre,sucursal,password) as 
  select x0.empresa ,x0.ejecutivo ,x0.nombre ,x0.sucursal ,x0.password 
    from bdinteg:"informix".si_ejecut x0 ;                    
                                                    
create view "informix".si_codret (codigo_retorno,sistema,descripcion) as 
  select x0.codigo_retorno ,x0.sistema ,x0.descripcion from bdinteg:
    "informix".si_codret x0 ;                                 
                                                             
      
create view "informix".si_contable (empresa,producto,sistema,transaccion,cuenta_cargo,cuenta_abono) as 
  select x0.empresa ,x0.producto ,x0.sistema ,x0.transaccion ,
    ((((((((((TRIM ( BOTH ' ' FROM x0.c_ccmayor ) || '-' ) || TRIM 
    ( BOTH ' ' FROM x0.c_ccsub ) ) || '-' ) || TRIM ( BOTH ' ' FROM 
    x0.c_ccsubsub ) ) || '-' ) || TRIM ( BOTH ' ' FROM x0.c_ccsssub 
    ) ) || '-' ) || TRIM ( BOTH '     ' FROM x0.c_ccssssub ) ) 
    || '-' ) || TRIM ( BOTH ' ' FROM x0.c_sector ) ) ,((((((((((TRIM 
    ( BOTH ' ' FROM x0.a_ccmayor ) || '-' ) || TRIM ( BOTH ' ' FROM 
    x0.a_ccsub ) ) || '-' ) || TRIM ( BOTH ' ' FROM x0.a_ccsubsub 
    ) ) || '-' ) || TRIM ( BOTH ' ' FROM x0.a_ccsssub ) ) || '-'
     ) || TRIM ( BOTH ' ' FROM x0.a_ccssssub ) ) || '-' ) || TRIM 
    ( BOTH ' ' FROM x0.a_sector ) ) from bdinteg:"informix".si_prodtran 
    x0 ;                                                     
                                                             
                                                             
                                                             
      
create view "informix".si_transacc (empresa,numero,descripcion,naturaleza,se_emite_edocta,se_contabiliza) as 
  select x0.empresa ,x0.numero ,x0.descripcion ,x0.naturaleza 
    ,x0.se_emite_edocta ,x0.se_contabiliza from bdinteg:"informix"
    .si_transacc x0 ;        
create view "informix".si_cliente (empresa,numcte,nombre,rfc,ejecutivo,curp,seguro_defunc,fecha_nac,fecha_alta,no_imss) as 
  select x0.empresa ,x0.numcte ,TRIM ( BOTH ' ' FROM (((((((TRIM 
    ( BOTH ' ' FROM NVL (x0.razon_social ,' ' )) || TRIM ( BOTH 
    ' ' FROM NVL (x0.nombre1 ,' ' )) ) || ' ' ) || TRIM ( BOTH ' '
     FROM NVL (x0.nombre2 ,' ' )) ) || ' ' ) || TRIM ( BOTH ' ' 
    FROM NVL (x0.apell_paterno ,' ' )) ) || ' ' ) || TRIM ( BOTH 
    ' ' FROM NVL (x0.apell_materno ,' ' )) ) ) ,x0.rfc ,x0.ejecutivo 
    ,x1.curp ,NVL (x1.seguro_defunc ,'0' ),x1.fecha_nac ,x0.fecha_alta 
    ,x1.no_imss from bdinteg:"informix".si_cliente x0 ,outer(bdinteg:
    "informix".si_ctepf x1 ) where (x0.numcte = x1.numcte ) ; 
                                                             
                               
create view "informix".si_direcciones (numcte,secuencia,calle,colonia,nommunicipio,nomestado,nomciudad,cod_postal,telefono1,telefono2,municipio) as 
  select x0.numcte ,x0.secuencia ,x0.calle ,x0.colonia ,x1.nombre 
    ,x2.nombre ,x3.nombre ,x0.cod_postal ,x0.telefono1 ,x0.telefono2 
    ,x0.municipio from bdinteg:"informix".si_direcciones x0 ,outer(bdinteg:
    "informix".si_municipios x1 ) ,bdinteg:"informix".si_estados 
    x2 ,bdinteg:"informix".si_ciudades x3 where (((((((((x1.municipio 
    = x0.municipio ) AND (x1.estado = x0.estado ) ) AND (x1.ciudad 
    = x0.ciudad ) ) AND (x1.pais = x0.pais ) ) AND (x2.estado 
    = x0.estado ) ) AND (x2.pais = x0.pais ) ) AND (x3.ciudad 
    = x0.ciudad ) ) AND (x3.estado = x0.estado ) ) AND (x3.pais 
    = x0.pais ) ) ;                                       
create view "informix".sc_maechqcifras (sdo_dia_ant) as 
