create trigger "informix".tr_sc_fechas_insert insert on "informix"
    .sc_fechas referencing new as nvo
    for each row
        (
        insert into "informix".sc_fechas (empresa,fecha_hoy,fecha_ant,
    prox_fecha,pri_dia_mes,pri_hab_mes,ult_dia_mes,ult_hab_mes,ind_cierre,
    ind_disponible)  values (nvo.empresa ,nvo.fecha_hoy ,nvo.fecha_ant 
    ,nvo.prox_fecha ,nvo.pri_dia_mes ,nvo.pri_hab_mes ,nvo.ult_dia_mes 
    ,nvo.ult_hab_mes ,nvo.ind_cierre ,nvo.ind_disponible ));

create trigger "informix".tr_sc_fechas_delete delete on "informix"
    .sc_fechas referencing old as ant
    for each row
        (
        delete from "informix".sc_fechas  where ((((((((((empresa 
    = ant.empresa ) AND (fecha_hoy = ant.fecha_hoy ) ) AND (fecha_ant 
    = ant.fecha_ant ) ) AND (prox_fecha = ant.prox_fecha ) ) AND (pri_dia_mes 
    = ant.pri_dia_mes ) ) AND (pri_hab_mes = ant.pri_hab_mes ) ) AND 
    (ult_dia_mes = ant.ult_dia_mes ) ) AND (ult_hab_mes = ant.ult_hab_mes 
    ) ) AND (ind_cierre = ant.ind_cierre ) ) AND (ind_disponible = ant.ind_disponible 
    ) ) );

create trigger "informix".tr_sc_maechq_insert insert on "informix"
    .sc_maechq referencing new as nvo
    for each row
        (
        insert into bdinteg:"informix".info_cuenta_pyt (num_cte,
    tipo_producto,num_cuenta,fecha_apertura,tipo,fecha_ctrl)  values 
    (nvo.num_cte ,nvo.producto ,nvo.cuenta ,TODAY ,'D' ,CURRENT year to 
    fraction(3) ));

create trigger "informix".tr_proacstatus update of status_cta 
    on "informix".sc_maechq referencing new as regmod
    for each row
        (
        execute procedure "informix".sp_proac_estatus(regmod.cuenta 
    ,regmod.status_cta ));

create trigger "informix".sc_tr_ctedigital insert on "informix"
    .sc_maechq referencing new as nuevo
    for each row
        (
        execute procedure bdinteg:"informix".sp_ctedigital_validaclientes(nuevo.num_cte 
    ,'2' ,'3' ));

create trigger "informix".tr_sc_maenoc_update update of fecha_alta 
    on "informix".sc_maenoc referencing new as updt
    for each row
        (
        insert into bdinteg:"informix".info_cuenta_pyt (num_cte,
    tipo_producto,num_cuenta,fecha_apertura,tipo,fecha_ctrl)  values 
    ('-' ,'-' ,updt.cuenta ,updt.fecha_alta ,'D' ,CURRENT year to fraction(3) 
    ));

create trigger "informix".tr_chqprod_delete delete on "informix"
    .sc_producto referencing old as borrado
    for each row
        (
        -- Hecho por: Manuel Osuna V. (26-DIC-2007)
        -- Proyecto Mis (Hoja de Comportamiento)
        delete from bdmis:"informix".mi_producto  where (borrado.producto 
    = num_producto ) );

create trigger "informix".tr_chqprod_insert insert on "informix"
    .sc_producto referencing new as new
    for each row
        when (((select count(*) from bdmis:"informix".mi_producto 
    x0 where (new.producto = x0.num_producto ) ) = 0. ) )
            (
            -- Hecho por: Manuel Osuna V. (26-DIC-2007)
            -- Proyecto Mis (Hoja de Comportamiento)
            insert into bdmis:"informix".mi_producto (empresa,
    num_producto,nombre,num_sistema,fecha)  values ('001' ,new.producto ,new.nombre 
    ,'01' ,new.feciniape ));

create trigger "informix".tr_chqprod_update update on "informix"
    .sc_producto referencing new as mod
    for each row
        (
        -- Hecho por: Manuel Osuna V. (26-DIC-2007)
        -- Proyecto Mis (Hoja de Comportamiento)
        update bdmis:"informix".mi_producto set bdmis:"informix"
    .mi_producto.nombre = mod.nombre  where (mod.producto = num_producto 
    ) );

create trigger "informix".tr_sc_producto_insert insert on "informix"
    .sc_producto referencing new as nvo
    for each row
