    on "informix".sc_contproc_corresp referencing old as ant new 
    as nvo
    for each row
        (
        update bdicheq@coppelcont_tcp:"informix".sc_contproc_corresp 
    set bdicheq@coppelcont_tcp:"informix".sc_contproc_corresp.empresa 
    = nvo.empresa ,bdicheq@coppelcont_tcp:"informix".sc_contproc_corresp.proceso 
    = nvo.proceso ,bdicheq@coppelcont_tcp:"informix".sc_contproc_corresp.fecha 
    = nvo.fecha  where ((empresa = ant.empresa ) AND (proceso = ant.proceso 
    ) ) );

create trigger "informix".tr_sc_contproc_corresp_delete delete 
    on "informix".sc_contproc_corresp referencing old as ant
    for each row
        (
        delete from bdicheq@coppelcont_tcp:"informix".sc_contproc_corresp 
     where ((empresa = ant.empresa ) AND (proceso = ant.proceso ) ) );
    

create trigger "informix".trg_portacec_update_orde_recep update 
    of cta_ordenante,cta_receptora on "informix".sc_portacec_solicitud 
    referencing old as pre new as pos
    for each row
        (
        execute procedure "informix".sp_notif_cambios_portacec() 
    with trigger references );

